import{z as B,x as i,o as t,c as p,q as A,j as r,D as E,d as o,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"局部投影","description":"","frontmatter":{"title":"局部投影","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/local-projections.md","filePath":"econ/local-projections.md","lastUpdated":1791063341000}'),d={name:"econ/local-projections.md"};function h(R,a,m,P,_,c){const n=i("Mermaid");return t(),p("div",null,[a[2]||(a[2]=A('<h1 id="局部投影" tabindex="-1">局部投影 <a class="header-anchor" href="#局部投影" aria-label="Permalink to &quot;局部投影&quot;">​</a></h1><div class="epigraph"><p>每一地平线单独回归，不必先估一个套牢所有 $h$ 的 VAR；识别仍然要来自别处。</p><footer>—— Jordà, Estimation and Inference of Impulse Responses by Local Projections, AER 2005</footer></div><p><a href="/econ/svar-identification">上一课</a>用 VAR 的结构冲击生成所有地平线的 IRF。本课缺口是<strong>换估计器</strong>：局部投影（LP）把 \\(y_{t+h}\\) 直接投到冲击或工具上。不重写 \\(A_0\\) 的全部菜单，也不宣称 LP 免除识别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VAR 的 IRF 是迭代：\\(C_h\\) 由同伴矩阵的幂给出，设定误差会随 \\(h\\) 累积。Jordà：对每个 \\(h\\) 估计</p> \\[y_{t+h}=\\alpha_h+\\beta_h\\varepsilon_t+\\gamma_h(L)X_t+u_{t+h}, \\]<p>\\(\\beta_h\\) 就是该地平线的脉冲。\\(\\varepsilon_t\\) 仍须是结构的：来自 SVAR、来自叙事、来自高频工具。缺口是把「IRF 的估计」从「VAR 设定」里拆出来，而不是再发明一种冲击。</p><p><span class="marginnote">直觉类比：VAR 像用一条万能公式从今天一路推算到十年后——省参数，但公式错一步，误差滚雪球；LP 像每个年份另请一位向导各自报价——彼此不抄答案，报价之间可能上下打架（毛刺），但谁也别想用自己的错误污染别人的估计。</span></p><p><span class="marginnote">Jordà, <em>AER</em> 95(1), 2005, 161–182。Plagborg-Møller and Wolf：在线性、正确设定且滞后足够时，LP 与 VAR 的 IRF 渐近谈的是同一对象，差别在有限样本偏差–方差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>冲击已知时，LP 是一串 OLS（或 IV）。冲击要估计时，先做识别步骤，再投影。推断：重叠地平线使 \\(u_{t+h}\\) 序列相关，用 Newey–West 或滞后增广（Rambachan–Shephard、Montiel Olea 等讨论）。平滑 LP 把相邻 \\(h\\) 的 \\(\\beta_h\\) 借强度，回到一点 VAR 的味道。非线性：把状态（衰退、ZLB、债务高）放进交互，LP 比 VAR 更容易写成状态依存 IRF。</p>',11)),(t(),r(s,null,{default:E(()=>[l(n,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E8%AF%86%E5%88%AB%E5%BE%97%E5%88%B0%20%CE%B5%20%E6%88%96%E5%B7%A5%E5%85%B7%22%5D%20--%3E%20LP%5B%22%E5%90%84%20h%20%E7%9A%84%E5%9B%9E%E5%BD%92%22%5D%0A%20%20LP%20--%3E%20IRF%5B%22%CE%B2_h%20%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20VAR%5B%22VAR%20%E8%BF%AD%E4%BB%A3%22%5D%20--%3E%20IRF2%5B%22%E5%90%8C%E4%BC%B4%E7%9F%A9%E9%98%B5%E5%B9%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"财政乘数、货币脉冲的近期文献大量用 LP，正是因为状态依存与较少的动态套牢。识别差时，LP 只是更灵活地报错。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是避免用错误的 VAR 动态去外推远地平线。代价是方差大、曲线毛。VAR 是收缩：所有 \\(h\\) 共享参数。选择不是哲学，是偏差–方差。两者都要求条件均值线性或你已经把非线性写进回归。预期：若冲击被预见，无论 LP 还是 VAR 都会在 \\(t\\) 之前动——新闻冲击课再处理。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：「偏差–方差权衡」是统计学的老账——模型越僵硬（参数少、全 \\(h\\) 共享），错得稳定但可能整体偏；模型越灵活（每个 \\(h\\) 各估各的），不容易整体偏但单个估计抖得厉害。LP 与 VAR 的选择不是谁更「真」，是你在这条权衡上站哪头。")],-1)),(t(),r(s,null,{default:E(()=>[l(n,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAR%5B%22VAR%3A%20%E6%89%80%E6%9C%89%20h%20%E5%85%B1%E4%BA%AB%E4%B8%80%E5%A5%97%E5%8F%82%E6%95%B0%22%5D%20--%3E%20ITER%5B%22%E8%BF%AD%E4%BB%A3%E5%90%8C%E4%B8%80%E7%A7%8D%E5%8A%A8%E6%80%81%22%5D%0A%20%20ITER%20--%3E%20BIAS%5B%22%E8%AE%BE%E5%AE%9A%E8%AF%AF%E5%B7%AE%E9%9A%8F%20h%20%E7%B4%AF%E7%A7%AF%2C%20%E4%BD%86%E6%9B%B2%E7%BA%BF%E5%B9%B3%E6%BB%91%22%5D%0A%20%20LP%5B%22LP%3A%20%E6%AF%8F%E4%B8%AA%20h%20%E5%8D%95%E7%8B%AC%E5%9B%9E%E5%BD%92%22%5D%20--%3E%20FREE%5B%22%E5%90%84%E5%9C%B0%E5%B9%B3%E7%BA%BF%E4%BA%92%E4%B8%8D%E5%A5%97%E7%89%A2%22%5D%0A%20%20FREE%20--%3E%20HAIRY%5B%22%E6%9B%B2%E7%BA%BF%E6%AF%9B%2C%20%E5%8D%95%E7%82%B9%E6%96%B9%E5%B7%AE%E5%A4%A7%22%5D%0A%20%20BIAS%20--%3E%20CHOICE%5B%22%E4%BC%B0%E8%AE%A1%E5%99%A8%E7%9A%84%E9%80%89%E6%8B%A9%E6%98%AF%E5%81%8F%E5%B7%AE-%E6%96%B9%E5%B7%AE%E6%9D%83%E8%A1%A1%22%5D%0A%20%20HAIRY%20--%3E%20CHOICE%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p>与 DSGE：LP 的 \\(\\beta_h\\) 可当要匹配的半结构靶（Christiano–Eichenbaum–Evans 传统的 IRF 匹配），参数化仍回校准或估计课。</p><p><span class="marginnote">识别与估计分工：Stock–Watson 的外部工具可以进 SVAR，也可以进 LP-IV。后课叙事与高频，是工具的来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供新的冲击序列。不把 LP 写成「比结构模型更真」。面板 LP、区域乘数（Nakamura–Steinsson）是同一估计器的另一数据，本课只钉时间序列宏观。微观结构的脉冲（订单流）不在本栏。</p><p>后课默认：IRF 可用 VAR 或 LP 估；识别另给。下一课：叙事日期与高频意外如何提供那条识别。</p><p><span class="marginnote">常见误区：初学者容易以为「换用 LP 就不用做识别了」——LP 换的只是估计器，\\(\\varepsilon_t\\) 从哪里来（SVAR、叙事、高频工具）一步都不能少；识别差时，LP 只是更灵活地把错误画出来，不会把坏冲击变成好冲击。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LP：每地平线回归，少套牢动态，多方差。</li><li>识别不因 LP 而消失。</li><li>线性正确设定下，与 VAR 谈同一 IRF。</li><li>出处：Jordà, <em>AER</em> 2005。</li></ul>',8))])}const L=B(d,[["render",h]]);export{F as __pageData,L as default};
